import pathlib
roots=[pathlib.Path('node_modules/@shikijs'), pathlib.Path('node_modules/shiki')]
for root in roots:
    if not root.exists():
        print('missing', root); continue
    for p in root.rglob('*'):
        if not p.is_file(): continue
        if p.suffix not in {'.mjs','.js','.cjs'}: continue
        if 'langs' in p.parts or 'themes' in p.parts: continue
        try:
            t=p.read_text(errors='ignore')
        except Exception:
            continue
        if 'shiki-dark' in t or '--shiki' in t:
            print(p)
